cat > /tmp/q3.js <<'EOF'
const {DatabaseSync}=require('node:sqlite');
const db=new DatabaseSync('/bench/home/work/.codegraph/codegraph.db',{readOnly:true});
const sql=`select n.name, n.file_path, n.start_line, n.kind, e.metadata, s.file_path as cf, s.name as caller
from nodes n join edges e on e.target=n.id join nodes s on s.id=e.source
where e.kind='calls' and n.file_path like 'internal/%' and n.kind in ('function','method')`;
const rows=db.prepare(sql).all();
const agg={};
for(const r of rows){
  const key=r.name+'|'+r.file_path+':'+r.start_line;
  const m=r.metadata?JSON.parse(r.metadata):{};
  const a=(agg[key] ||= {callers:new Set(), files:new Set(), refs:{}, edges:0});
  a.edges++; a.callers.add(r.cf+'::'+r.caller); a.files.add(r.cf);
  a.refs[m.refName||'?']=(a.refs[m.refName||'?']||0)+1;
}
const list=Object.entries(agg).map(([k,a])=>({k,c:a.callers.size,f:a.files.size,e:a.edges,refs:Object.entries(a.refs).sort((x,y)=>y[1]-x[1]).slice(0,4)}));
list.sort((a,b)=>b.c-a.c);
for(const r of list.slice(0,30)) console.log(String(r.c).padStart(4),'files='+r.f,'edges='+r.e,'|',r.k,'|',JSON.stringify(r.refs));
EOF
